select release_key,release_no,record_count,adoption_scope,source_fingerprint from master.master_releases where release_key='cm.release.airtable.operational-master.v4';
select workspace_id,count(*) as catalog_count,count(*) filter(where availability_status='active') as active_count,count(*) filter(where availability_status='paused') as paused_count from public.order_catalog_items where workspace_id in ('workspace-clinical-master-pilot-v1','workspace-clair-cheongdam','clair-demo','clair-foreign-demo') group by workspace_id order by workspace_id;
select workspace_id,count(*) as set_count,count(*) filter(where availability_status='active') as active_set_count from public.order_sets where workspace_id in ('workspace-clinical-master-pilot-v1','workspace-clair-cheongdam','clair-demo','clair-foreign-demo') group by workspace_id order by workspace_id;
